	,generateSong: function() {
		if(this.get_currentChart() == null) {
			throw haxe_Exception.thrown("Song difficulty could not be loaded.");
		}
		if(!this.overrideMusic) {
			var tmp = this.vocals;
			if(tmp != null) {
				tmp.stop();
			}
			var tmp = this.get_currentChart();
			this.vocals = tmp != null ? tmp.buildVocals(this.currentInstrumental) : null;
			var tmp = this.vocals;
			var tmp1 = tmp != null ? tmp.members : null;
			if((tmp1 != null ? tmp1.length : null) == 0) {
				haxe_Log.trace("WARNING: No vocals found for this song.",{ fileName : "source/funkin/play/PlayState.hx", lineNumber : 2448, className : "funkin.play.PlayState", methodName : "generateSong"});
			}
		}
		this.regenNoteData(this.startTimestamp);
		funkin_modding_events_ScriptEventDispatcher.callEvent(this.currentSong,new funkin_modding_events_ScriptEvent("CREATE",false));
		this.generatedMusic = true;
	}
	,regenNoteData: function(startTime) {
		if(startTime == null) {
			startTime = 0;
		}
		if(this.get_currentChart() == null) {
			haxe_Log.trace("Cannot regenerate note data for null chart",{ fileName : "source/funkin/play/PlayState.hx", lineNumber : 2467, className : "funkin.play.PlayState", methodName : "regenNoteData"});
			return;
		}
		funkin_Highscore.tallies.combo = 0;
		funkin_Highscore.tallies = funkin_Tallies._new();
		var event = new funkin_modding_events_SongLoadScriptEvent(this.get_currentChart().song.id,this.get_currentChart().difficulty,this.get_currentChart().notes.slice(),this.get_currentChart().getEvents());
		this.dispatchEvent(event);
		var builtNoteData = event.notes;
		this.songEvents = event.events;
		funkin_data_event_SongEventRegistry.resetEvents(this.songEvents);
		var playerNoteData = [];
		var opponentNoteData = [];
		var _g = 0;
		while(_g < builtNoteData.length) {
			var songNote = builtNoteData[_g];
			++_g;
			if(songNote.time < startTime) {
				continue;
			}
			var scoreable = true;
			if(songNote.get_kind() != null) {
				var tmp = songNote.get_kind();
				var noteKind = funkin_play_notes_notekind_NoteKindManager.getNoteKind(tmp != null ? tmp : "");
				if(noteKind != null) {
					scoreable = noteKind.scoreable;
				}
			}
			var noteData = songNote.data;
			switch(songNote.getStrumlineIndex()) {
			case 0:
				if(this.mirrorSongData) {
					songNote.data = funkin_util_GRhythmUtil.mirrorNoteDirection(noteData);
				}
				playerNoteData.push(songNote);
				if(scoreable) {
					funkin_Highscore.tallies.totalNotes++;
				}
				break;
			case 1:
				if(this.mirrorSongData) {
					songNote.data = funkin_util_GRhythmUtil.mirrorNoteDirection(noteData);
				}
				opponentNoteData.push(songNote);
				break;
			}
		}
		this.playerStrumline.applyNoteData(playerNoteData);
		this.opponentStrumline.applyNoteData(opponentNoteData);
	}
